  function createTripleTSounds(context, output, isAudible) {
    const played = { step: 0, jump: 0, hurt: 0 };
    let foot = 0;
    let lastHurt = -Infinity;
    let sprintUntil = 0;

    function makeClip(encoded) {
      const bytes = atob(encoded);
      const buffer = context.createBuffer(1, bytes.length / 2, 24000);
      const channel = buffer.getChannelData(0);
      for (let frame = 0; frame < channel.length; frame++) {
        const sample = bytes.charCodeAt(frame * 2) | (bytes.charCodeAt(frame * 2 + 1) << 8);
        channel[frame] = (sample << 16 >> 16) / 32768;
      }
      return buffer;
    }

    const sprintClip = makeClip("");
    const jumpClip = makeClip("");
    const hurtClip = makeClip("");

    function playClip(buffer, volume, now) {
      const source = context.createBufferSource();
      const gain = context.createGain();
      source.buffer = buffer;
      gain.gain.value = volume;
      source.connect(gain);
      gain.connect(output);
      source.onended = () => {
        source.disconnect();
        gain.disconnect();
      };
      source.start(now);
    }

    function note(at, duration, shape, startHz, endHz, gain, filterHz) {
      const oscillator = context.createOscillator();
      const filter = context.createBiquadFilter();
      const envelope = context.createGain();
      oscillator.type = shape;
      oscillator.frequency.setValueAtTime(startHz, at);
      oscillator.frequency.exponentialRampToValueAtTime(endHz, at + duration * .9);
      filter.type = "lowpass";
      filter.frequency.value = filterHz;
      envelope.gain.setValueAtTime(.0001, at);
      envelope.gain.exponentialRampToValueAtTime(gain, at + .005);
      envelope.gain.exponentialRampToValueAtTime(.0001, at + duration);
      oscillator.connect(filter).connect(envelope).connect(output);
      oscillator.onended = () => {
        oscillator.disconnect();
        filter.disconnect();
        envelope.disconnect();
      };
      oscillator.start(at);
      oscillator.stop(at + duration + .006);
    }

    return {
      status: () => ({ state: context.state, played: { ...played } }),
      step(sprint) {
        if (!isAudible()) return;
        const now = context.currentTime;
        if (sprint) {
          if (now < sprintUntil) return;
          sprintUntil = now + sprintClip.duration;
          played.step++;
          playClip(sprintClip, .85, now);
          return;
        }
        played.step++;
        const pitch = [158, 177, 146][foot++ % 3];
        note(now, .105, "triangle", pitch * 1.35, pitch, .24, 1800);
        note(now, .022, "square", pitch * 5, pitch * 3, .065, 2400);
      },
      jump() {
        if (!isAudible()) return;
        const now = context.currentTime;
        played.jump++;
        playClip(jumpClip, .95, now);
      },
      hurt() {
        const now = context.currentTime;
        if (!isAudible() || now - lastHurt < hurtClip.duration) return;
        lastHurt = now;
        played.hurt++;
        playClip(hurtClip, .95, now);
      },
    };
  }
